Let $U$ be a   connected manifold of dimension $m>1$,  
     $T  $   a compact contractible set,  $T_1,\dots, T_k\subset T$ its  compact    subsets  such that
     \begin{description}
     \item{$(\star)$}   any      intersection 
      $T_{i_{1}}\cap \dots \cap T_{i_{p}}$ for $1\leq i_1<\dots<i_p\leq k$
      is  either empty or contractible. 
      \end{description}
      Let $B$ be a closed $m$-dimensional ball with a given point $p \in \partial B$,
         $S_j:T_j\times B\to T_j\times U$, 
        $S_j(\tau,x)=(\tau,s_j(\tau,x))$, and $S_\pm:T\times B\to T\times U$, $S_\pm(\tau,x)=(\tau,s_\pm(\tau,x))$, be pairwise disjoint fiberwise smooth embeddings.
         Then there exists a fiberwise embedding $S:T\times[-1,1]\to T\times U$  such that
     \begin{enumerate}
    \item  $S(\tau,\pm 1)=S_\pm(\tau,p)$, $\tau\in T$;
      \item $S (T\times[-1,1])\cap\bigcup\limits_1^kS_j(T_j\times B)=\varnothing$;
      \item $S (T\times(-1,1))\cap\left(S_-(T\times B)\cup S_+(T\times B)\right)=\varnothing$.
\end{enumerate}

There is a family of contact embeddings for $\sigma\in[0,1]$
	$$
		\Theta_\sigma: \Delta \to \Delta\#_{\beta, \ell}\Delta \quad\mbox{with
		$\Theta_\sigma = Z_{1+\ell}$ on ${\mathcal O}{\it p}\,\{z \in [z_D, 1]\}$}
	$$
	based at $\Theta_0 := Z_{1+\ell}$ such that
	\begin{enumerate}
	\item $\left((\Theta_1)_*K' ,\Theta_1(\Delta')\right) < \left(K\#_\beta K, \Delta\#_{\beta, \ell}\Delta\right)$ and
	\item $\left((\Theta_\sigma)_*K',\Theta_\sigma(\Delta')\right) < \left(E\#_\beta K, \Delta\#_{\beta, \ell}\Delta\right)$ for all $\sigma \in [0,1]$.
	\end{enumerate}
